css:
.engine-visual {
  position: fixed;
  z-index: 3;
  left: 50%;
  top: -15px;
  width: auto;
  height: calc((100% + 15px) * 1.4);
  max-width: calc(100vw - 96px);
  max-height: 1023px;
  aspect-ratio: 2 / 3;
  transform: translate3d(-50%, var(--scroll-y, 0px), 0);
  will-change: transform, opacity;
  filter: drop-shadow(0 28px 34px rgb(26 31 42 / 0.22));
}
